  if (!atom) return 0;
  uint8_t len = atom->length;
  if (len > 32) len = 32;
  int score = 0;
  for (uint8_t i = 0; i < len; ++i) {
    uint8_t m = atom->mask[i];
    m = (m & 0x55) + ((m >> 1) & 0x55);
    m = (m & 0x33) + ((m >> 2) & 0x33);
    m = (m & 0x0F) + ((m >> 4) & 0x0F);
    score += (int)m;
  }
  return score;
};

