stream->user_data = state;
stream->read = +[](void* ptr, size_t size, size_t count, void* user_data) -> size_t {
  if (!ptr || size == 0 || count == 0) return 0;
  RWState* st = (RWState*) user_data;
  size_t remaining = (st->rpos < st->buf.size()) ? (st->buf.size() - st->rpos) : 0;
  size_t avail_items = remaining / size;
  size_t to_read = avail_items < count ? avail_items : count;
  if (to_read == 0) return 0;
  size_t bytes = to_read * size;
  memcpy(ptr, st->buf.data() + st->rpos, bytes);
  st->rpos += bytes;
  return to_read;
};
stream->write = +[](const void* ptr, size_t size, size_t count, void* user_data) -> size_t {
  if (!ptr || size == 0 || count == 0) return 0;
  RWState* st = (RWState*) user_data;
  size_t bytes = size * count;
  if (bytes > 2048) bytes = 2048; // cap growth per call
  st->buf.append((const char*)ptr, bytes);
