import random
from typing import List

def _rand_ident(r: random.Random, min_len=3, max_len=12) -> str:
    letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'
    letters_d = letters + '0123456789'
    n = r.randint(min_len, max_len)
    s = r.choice(letters)
    s += ''.join(r.choice(letters_d) for _ in range(n-1))
    return s

def _random_string_literal(r: random.Random) -> str:
    # Generate a string literal suitable for YARA text strings
    choices = [
        "Hello, world!",
        "malware",
        "PE\x00\x00",
        "This is a test",
        "\"quoted\"",
        "abc123",
        "kernel32.dll",
        "password",
        "config",
        "http://example.com"
    ]
    base = r.choice(choices)
    # Occasionally add modifiers
    mods = []
    if r.random() < 0.4:
        mods.append("nocase")
    if r.random() < 0.25:
        mods.append("wide")
    if r.random() < 0.2:
        mods.append("ascii")
    if r.random() < 0.15:
        # add private flag sometimes
        base = base  # string itself unchanged; we'll add private in string decl
    mod_str = " " + " ".join(mods) if mods else ""
    return f"\"{base}\"{mod_str}"

def _random_hex_pattern(r: random.Random) -> str:
    # YARA hex pattern like { 4D 5A ?? 90 [1-5] 00 }
    parts: List[str] = []
    # Start with a recognizable header sometimes
    if r.random() < 0.5:
        parts += ["4D", "5A"]  # MZ
    for _ in range(r.randint(3, 10)):
        p = r.random()
        if p < 0.6:
            parts.append(f"{r.randrange(256):02X}")
        elif p < 0.8:
            parts.append("??")
        else:
            a = r.randint(0, 5)
            b = r.randint(a+1, a+8)
            parts.append(f"[{a}-{b}]")
    return "{ " + " ".join(parts) + " }"

def _random_regex(r: random.Random) -> str:
    # Simple regexes that YARA can parse
    atoms = ["foo", "bar", "baz", "[A-Za-z]{3,6}", "(test|prod)", "a+b?", ".{2,8}"]
    s = r.choice(atoms)
    flags = []
    if r.random() < 0.4:
        flags.append("nocase")
    return f"/{s}/" + (" " + " ".join(flags) if flags else "")

def _gen_meta_block(r: random.Random) -> str:
    lines = []
    # Include a mix of string, int, and bool metas
    if r.random() < 0.8:
        lines.append(f"author = \"{_rand_ident(r,5,10)}\"")
    if r.random() < 0.7:
        lines.append(f"version = {r.randint(1,5)}")
    if r.random() < 0.6:
        lines.append(f"stable = {r.choice(['true','false'])}")
    return ("  meta:\n" + ''.join(f"    {ln}\n" for ln in lines)) if lines else ""

def _gen_strings_block(r: random.Random) -> str:
    n = r.randint(1, 6)
    lines = []
    for i in range(n):
        name = f"${_rand_ident(r,3,8)}"
        kind = r.random()
        attrs = []
        if r.random() < 0.25:
            attrs.append("private")
        if kind < 0.5:
            val = _random_string_literal(r)
        elif kind < 0.8:
            val = _random_hex_pattern(r)
        else:
            val = _random_regex(r)
        suffix = (" " + " ".join(attrs)) if attrs else ""
        lines.append(f"    {name} = {val}{suffix}")
    return "  strings:\n" + "\n".join(lines) + "\n"

def _gen_condition(r: random.Random, defined_strings: List[str]) -> str:
    simple_opts = ["true", "false", "any of them", "all of them"]
    if defined_strings and r.random() < 0.7:
        # Create a condition referencing some strings
        picked = r.sample(defined_strings, k=max(1, min(len(defined_strings), r.randint(1,3))))
        # Use count, at, in, or of
        choice = r.random()
        if choice < 0.3:
            # count of strings
            return " or ".join([f"#${s} > {r.randint(0,2)}" for s in picked])
        elif choice < 0.6:
            # string found
            return " or ".join([f"${s}" for s in picked])
        else:
            # of them with threshold
            n = r.randint(1, len(defined_strings))
            return f"{n} of them"
    return r.choice(simple_opts)

def _gen_rule(r: random.Random, namespace: str | None) -> str:
    rulename = _rand_ident(r, 6, 14)
    tags = []
    if r.random() < 0.5:
        tags.append(_rand_ident(r,3,8))
    if r.random() < 0.25:
        tags.append(_rand_ident(r,3,8))
    tag_str = (" : " + " ".join(tags)) if tags else ""
    ns_prefix = f"// namespace: {namespace}\n" if namespace else ""

    meta = _gen_meta_block(r)

    strings_block = _gen_strings_block(r)
    # Collect string ids defined
    defined = []
    for line in strings_block.splitlines():
        line = line.strip()
        if line.startswith("$"):
            defined.append(line.split(" = ",1)[0][1:])

    condition = _gen_condition(r, defined)

    body = "rule " + rulename + tag_str + " {\n" + meta + strings_block + f"  condition:\n    {condition}\n" + "}\n"
    return ns_prefix + body

def _maybe_imports(r: random.Random) -> str:
    # Randomly add import statements for known built-in modules
    modules = ["pe", "elf", "cuckoo", "math", "hash", "dotnet"]
    imports = []
    for m in modules:
        if r.random() < 0.25:
            imports.append(f"import \"{m}\"")
    return ("\n".join(imports) + ("\n\n" if imports else ""))

def _gen_namespace_header(r: random.Random) -> str:
    # YARA allows specifying a namespace via the compiler API; within files you can also use 'namespace' directive.
    if r.random() < 0.4:
        return f"namespace {_rand_ident(r,5,12)}\n\n"
    return ""

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Compose a file containing valid YARA rules text; include a mixture of constructs
    parts: List[str] = []

    # Optional file-level namespace directive to exercise that path
    parts.append(_gen_namespace_header(r))

    # Optional module imports
    parts.append(_maybe_imports(r))

    # Generate 1-4 rules under potentially differing implied namespaces
    num_rules = r.randint(1, 4)
    for _ in range(num_rules):
        ns = _rand_ident(r, 5, 10) if r.random() < 0.5 else None
        parts.append(_gen_rule(r, ns))
        parts.append("\n")

    text = "".join(parts)

    # Ensure total size limit
    data = text.encode('utf-8')
    if len(data) > 4096:
        data = data[:4096]
    return data
